installer.script:
if (-not (Get-Command winget -ErrorAction SilentlyContinue)) { throw 'WinGet is required to install WidBar from the Microsoft Store.' }
winget install --id 9PKLDNM83TP9 --source msstore --exact --accept-source-agreements --accept-package-agreements
if ($LASTEXITCODE -ne 0) { throw "WinGet failed to install WidBar (exit code $LASTEXITCODE)." }

uninstaller.script:
if (-not (Get-Command winget -ErrorAction SilentlyContinue)) { throw 'WinGet is required to uninstall WidBar from the Microsoft Store.' }
winget uninstall --id 9PKLDNM83TP9 --source msstore --exact --accept-source-agreements
if ($LASTEXITCODE -ne 0) { throw "WinGet failed to uninstall WidBar (exit code $LASTEXITCODE)." }
